  1540	// agentSearchScoreTag renders the ` s=<n>` suffix for a block, or "" when the score carries
  1541	// no meaning. Related sites are not ranked answers — they are the other places the top hit's
  1542	// change usually has to land — and they carry no relevance score, so printing `s=0.0` beside
  1543	// one would read as "worthless" rather than "not applicable".
  1544	func agentSearchScoreTag(result sem.SearchResult) string {
  1545		if result.Section == sem.SearchSectionRelated || result.Section == sem.SearchSectionCoveringTest {
  1546			return ""
  1547		}
  1548		return fmt.Sprintf(" s=%.1f", result.Score)
  1549	}
