  1551	func agentSearchBlock(result sem.SearchResult, budget int) []byte {
  1552		// Every location header this block and its helpers emit is one line. See
  1553		// searchResultOnOneLine.
  1554		result = searchResultOnOneLine(result)
  1555		if len(result.Passages) == 0 {
  1556			return agentSearchPrimaryBlock(result, budget)
  1557		}
  1558		for count := len(result.Passages); count >= 0; count-- {
  1559			passages := renderAgentSearchPassages(result.FilePath, result.Passages[:count])
  1560			primaryBudget := budget
  1561			if budget > 0 && len(passages) > 0 {
  1562				primaryBudget -= len(passages) + 1
  1563				if primaryBudget <= 0 {
  1564					continue
  1565				}
  1566			}
  1567			primary := agentSearchPrimaryBlock(result, primaryBudget)
  1568			if len(primary) == 0 {
  1569				continue
  1570			}
  1571			if len(passages) == 0 {
  1572				return primary
  1573			}
  1574			combined := make([]byte, 0, len(primary)+1+len(passages))
  1575			combined = append(combined, primary...)
  1576			combined = append(combined, '\n')
  1577			combined = append(combined, passages...)
  1578			if budget <= 0 || len(combined) <= budget {
  1579				return combined
  1580			}
  1581		}
  1582		return nil
  1583	}
