  1585	func renderAgentSearchPassages(path string, passages []sem.SearchPassage) []byte {
  1586		var output bytes.Buffer
  1587		for index, passage := range passages {
  1588			if index > 0 {
  1589				output.WriteByte('\n')
  1590			}
  1591			fmt.Fprintf(&output, "%s:%d-%d [additional focus:%d]\n%s",
  1592				path, passage.StartLine, passage.EndLine, passage.FocusLine, passage.Snippet)
  1593		}
  1594		return output.Bytes()
  1595	}
